-- Migration 051: versione più breve dell'articolo sul rientro anticipato
-- (migration 049), in linea con la lunghezza degli altri articoli News.
-- Stessi esempi numerici e stessi link interni.

UPDATE news_articles SET body = '<p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con il <strong>rientro anticipato</strong>, o estinzione parziale, versi alla banca una somma in più rispetto alla rata. Va tutta a capitale e, con l''<a href="/news/ammortamento-alla-francese-guida-mutuo-rata-costante" class="text-accent hover:underline font-medium">ammortamento alla francese</a>, cancella gli interessi che avrebbe prodotto fino alla fine del mutuo. Per i mutui stipulati da persone fisiche dal 2 febbraio 2007 per acquistare o ristrutturare un immobile adibito ad abitazione o alla propria attività, le penali non sono ammesse. Negli altri casi controlla il contratto.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Ridurre la durata o la rata</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Dopo il versamento puoi tenere la rata uguale e finire prima (<strong>riduzione della durata</strong>), oppure tenere la scadenza e pagare una rata più bassa (<strong>riduzione della rata</strong>). Un esempio: mutuo prima casa da 150.000 euro al 3,5% in 25 anni. Dopo 5 anni il debito residuo è di circa 129.500 euro, la rata di 750,94 euro, e versi 10.000 euro.</p><ul class="mb-4 list-disc space-y-2 pl-5 text-[15px] leading-relaxed text-gray-700"><li><strong>Riducendo la durata</strong> il mutuo finisce 2 anni e 1 mese prima e risparmi circa <strong>9.340 euro</strong> di interessi.</li><li><strong>Riducendo la rata</strong> paghi 692,77 euro al mese (58 in meno) e risparmi circa <strong>3.900 euro</strong>.</li></ul><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con la rata invariata il debito si azzera prima e smette di produrre interessi, quindi si risparmia di più. Ridurre la rata ha senso se il bilancio mensile è stretto o se il tasso è variabile e temi rialzi. Non tutte le banche offrono entrambe le opzioni: chiedilo prima.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Puoi anche versare un importo fisso ogni anno. Con 2.000 euro all''anno, nello stesso esempio, il mutuo finisce quasi 5 anni prima e risparmi circa 13.800 euro. Però prima versi, più risparmi: ogni euro versato oggi taglia più anni di interessi di uno versato tra dieci anni.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">La detrazione persa</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Sul mutuo per l''abitazione principale recuperi il 19% degli interessi, fino a 4.000 euro di interessi l''anno (vedi la guida alla <a href="/news/detrazione-interessi-mutuo-prima-casa" class="text-accent hover:underline font-medium">detrazione degli interessi</a>). Pagando meno interessi recuperi meno: nell''esempio il risparmio netto scende a circa <strong>7.710 euro</strong> riducendo la durata e a circa <strong>3.300 euro</strong> riducendo la rata. La perdita non è sempre il 19%, perché gli interessi sopra il tetto annuo non erano comunque detraibili.</p><h2 class="mt-10 mb-3 text-xl font-bold text-gray-900">Conviene davvero?</h2><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Finché sei sotto il tetto, un mutuo al 3,5% "rende" circa il 2,8% netto, senza rischio. È il numero da confrontare con le alternative al netto delle tasse, come un <a href="/news/etf-monetari-o-conto-deposito" class="text-accent hover:underline font-medium">conto deposito</a> (al 3% lordo, circa il 2,2% netto) o gli investimenti, di cui parliamo in <a href="/news/estinzione-anticipata-mutuo-quando-conviene" class="text-accent hover:underline font-medium">quando conviene l''estinzione anticipata</a>. Prima di versare, assicurati di avere un <a href="/news/fondo-di-emergenza-quanto-tenere-da-parte" class="text-accent hover:underline font-medium">fondo di emergenza</a> e di aver chiuso eventuali debiti più cari.</p><p class="mb-4 text-[15px] leading-relaxed text-gray-700">Con <a href="/mutui" class="text-accent hover:underline font-medium">la sezione mutui di Reflexi</a> simuli il rientro sul tuo mutuo reale, una tantum o periodico, a riduzione della durata o della rata: il risparmio netto tiene già conto della detrazione persa anno per anno. Quando il versamento lo fai davvero, lo registri e il piano si aggiorna da solo.</p>', updated_at = NOW()
WHERE slug = 'rientro-anticipato-mutuo-ridurre-durata-o-rata';
